    bool inside = false;
    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        if (((poly[i].y() > p.y()) != (poly[j].y() > p.y())) &&
            (p.x() < (poly[j].x() - poly[i].x()) * (p.y() - poly[i].y()) / (poly[j].y() - poly[i].y()) + poly[i].x())) {
            inside = !inside;
        }
    }
    return inside;
};

if (is_inside(p1_points[0], p2_points)) return true;
if (is_inside(p2_points[0], p1_points)) return true;

